//! A struct generated by `macro_rules!`, with its field types, array length
//! and `Word` forwarded as `ty`/`literal` fragments. The compiler hands those
//! to the derive wrapped in invisible (`None`-delimited) groups, which the
//! derive must look through just as if they were written inline.

use pyroformat::{Layout, Reader, Realize, Writer};

macro_rules! pyro_struct {
    ($name:ident, $word:ty, $scalar:ty, $elem:ty, $n:literal) => {
        #[derive(Layout, Writer, Reader, Debug, PartialEq)]
        #[pyro(Word = $word)]
        struct $name {
            scalar: $scalar,
            list: Vec<$elem>,
            fixed: [$elem; $n],
        }
    };
}

pyro_struct!(Forwarded32, u32, u64, u16, 3);
pyro_struct!(Forwarded16, u16, i8, f32, 2);

fn main() {
    let data = Forwarded32 { scalar: 7, list: vec![1, 2], fixed: [3, 4, 5] };
    let buf = data.encode().unwrap();
    assert_eq!(Forwarded32::pyro_read(&buf).unwrap().realize(), data);

    let data = Forwarded16 { scalar: -1, list: vec![0.5], fixed: [1.5, 2.5] };
    let buf = data.encode().unwrap();
    assert_eq!(Forwarded16::pyro_read(&buf).unwrap().realize(), data);
}
